<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/Core.php';use Wams\Core;$c=new Core();$error='';$done=false;
if((int)$c->db->query('SELECT COUNT(*) FROM users')->fetchColumn()>0){http_response_code(404);exit;}
if($_SERVER['REQUEST_METHOD']==='POST')try{$username=trim((string)$_POST['username']);$password=(string)$_POST['password'];$repo=trim((string)$_POST['repository']);if($username===''||strlen($password)<12)throw new RuntimeException('Passwort muss mindestens 12 Zeichen lang sein.');$c->setSetting('app_repository',$repo);$c->refreshRepo();$c->db->prepare('INSERT INTO users VALUES(?,?,?,?,?,?)')->execute([$c->id(),$username,password_hash($password,PASSWORD_ARGON2ID),1,1,gmdate('c')]);$done=true;}catch(Throwable$e){$error=$e->getMessage();}
function h(mixed$v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>:root{color-scheme:dark}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#080c11;color:#e7edf4;font:13px system-ui}.box{width:390px;max-width:calc(100% - 28px);background:#111923;border:1px solid #293747;padding:22px}label{display:block;margin:11px 0 5px}input{width:100%;box-sizing:border-box;padding:9px;background:#0c1219;color:#fff;border:1px solid #293747}button{width:100%;margin-top:15px;padding:9px;background:#56a5ff;border:0}.error{padding:10px;background:#2a1419}</style><title>WAMS Setup</title></head><body><main class="box"><h1>WAMS</h1><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><?php if($done):?><p>Einrichtung abgeschlossen.</p><a href="/login">Zur Anmeldung</a><?php else:?><form method="post"><label>Benutzername</label><input name="username" required><label>Passwort</label><input type="password" name="password" minlength="12" required><label>App-Repository</label><input type="url" name="repository" value="https://github.com/florianthepro/webapp-foundry" required><button>Einrichten</button></form><?php endif?></main></body></html>
